// @FIGURE_CODE_BEGIN
var FW = 900, FH = 430;
var fdraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
fdraw.viewbox(0, 0, FW, FH);

var CY = 170, RAD = 125, LCX = 250, RCX = 650, MID = 450;
var GLASS_EDGE = '#a3c4c8', GLASS_FILL = '#dcecec';
var METAL = '#c6dde0', METAL_EDGE = '#9cc0c4';
var RED = '#d8241f', WHITE = '#ffffff', WHITE_EDGE = '#c3d2d2', TXT = '#333333';

/* ---------- deterministic randomness ---------- */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var rng = mulberry32(20240614);

function samplePts(cx, cy, r, n, minD, rnd) {
  var pts = [], guard = 0;
  while (pts.length < n && guard < 40000) {
    guard++;
    var a = rnd() * Math.PI * 2, rr = r * Math.sqrt(rnd());
    var x = cx + rr * Math.cos(a), y = cy + rr * Math.sin(a), ok = true;
    for (var i = 0; i < pts.length; i++) {
      var dx = x - pts[i][0], dy = y - pts[i][1];
