/* ---------- molecules ---------- */
var leftSlots = shuffle(samplePts(LCX, CY, RAD - 18, 46, 24, rng), rng);
var rightSlots = shuffle(samplePts(RCX, CY, RAD - 18, 47, 24, rng), rng);
while (leftSlots.length < 46) leftSlots.push([LCX, CY]);
while (rightSlots.length < 47) rightSlots.push([RCX, CY]);

