for (i = 0; i < 30; i++) {
  mols.push({
    kind: 'H2', idx: i, N: 30,
    home: leftSlots[i],
    away: i < 15 ? rightSlots[32 + i] : leftSlots[i],
    rad: 6.0, wob: 3.4, sp1: 1.8 + rng() * 1.4, sp2: 1.7 + rng() * 1.4,
    phase: rng() * 6.28, dir: rng() * 6.28, tubeOff: rng() * 20 - 10
