for (i = 0; i < 32; i++) {
  mols.push({
    kind: 'O2', idx: i, N: 32,
    home: rightSlots[i],
    away: i < 16 ? leftSlots[30 + i] : rightSlots[i],
    rad: 6.5, wob: 1.5, sp1: 0.5 + rng() * 0.4, sp2: 0.5 + rng() * 0.4,
    phase: rng() * 6.28, dir: rng() * 6.28, tubeOff: rng() * 20 - 10
  });
