var gBack = fdraw.group(), gApp = fdraw.group(), gTrail = fdraw.group(),
    gDot = fdraw.group(), gLab = fdraw.group();

/* dashed divider at the stopcock */
gBack.line(MID, 40, MID, 310).stroke({ color: '#b3c9cc', width: 1.5, dasharray: '5,6' }).opacity(0.75);

/* connecting tube */
gApp.rect(184, 42).move(MID - 92, CY - 21).radius(6)
  .fill(GLASS_FILL).stroke({ color: GLASS_EDGE, width: 4 });

