  c.css('cursor', 'pointer');
  c.on('mousemove', function (e) { showTooltip(name + ' bulb — click for the gradient story', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Concentration gradient',
        'Each gas starts entirely in one bulb, i.e. at maximum concentration on one side and zero on the other. ' +
        'Random molecular motion moves molecules in both directions, but more start on the crowded side, so the net flow is always down the gradient until both bulbs hold the same mixture.');
    });
