/* stopcock */
var gValve = gApp.group();
gValve.rect(14, 42).move(MID - 7, 110).radius(3).fill(METAL).stroke({ color: METAL_EDGE, width: 2 });
gValve.ellipse(52, 14).center(MID, 110).fill(METAL).stroke({ color: METAL_EDGE, width: 2 });
gValve.ellipse(14, 10).center(MID, 100).fill(METAL).stroke({ color: METAL_EDGE, width: 2 });
gValve.rect(38, 58).move(MID - 19, 141).radius(7).fill(METAL).stroke({ color: METAL_EDGE, width: 2.5 });
gValve.rect(18, 20).move(MID - 9, 196).fill(METAL).stroke({ color: METAL_EDGE, width: 2 });
gValve.ellipse(30, 10).center(MID, 216).fill(METAL).stroke({ color: METAL_EDGE, width: 2 });
