var boreOpen = gValve.rect(38, 24).move(MID - 19, CY - 12).radius(4)
  .fill(GLASS_FILL).stroke({ color: METAL_EDGE, width: 1.5 }).opacity(0);
gValve.css('cursor', 'pointer');
gValve.on('mousemove', function (e) { showTooltip('Stopcock — the only path between the bulbs', e); })
  .on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('Diffusion needs no pump',
      'Opening the stopcock adds no force and no fan. Molecules simply continue their random, high-speed motion, and that alone erases the concentration difference. ' +
      'At equilibrium molecules still stream through the bore constantly — just equally in both directions.');
  });

