/* ---------- labels ---------- */
function plain(g, s, x, y, size, color, anchor, weight) {
  var t = g.plain(s).font({ family: 'sans-serif', size: size, fill: color || TXT, weight: weight || 'normal' });
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle' });
  return t;
}
function gasLabel(cx, sym) {
  plain(gLab, sym, cx - 1, 34, 23, TXT, 'end');
