gLegend.rect(262, 62).move(14, 338).radius(6).fill('#f1f8f8').stroke({ color: '#cfe0e1', width: 1 });
gLegend.line(30, 358, 54, 358).stroke({ color: '#ffffff', width: 4, linecap: 'round' });
gLegend.circle(12).center(58, 358).fill(WHITE).stroke({ color: WHITE_EDGE, width: 1 });
plain(gLegend, 'H₂  2 g/mol — fast (long trail)', 70, 362, 12, '#33474a', 'start');
gLegend.line(46, 382, 54, 382).stroke({ color: RED, width: 4, linecap: 'round', opacity: 0.5 });
gLegend.circle(13).center(58, 382).fill(RED);
plain(gLegend, 'O₂  32 g/mol — slow (short trail)', 70, 386, 12, '#33474a', 'start');

/* ---------- state + render ---------- */
var state = { t: 0, mass: false, playing: false };

function render(tt) {
  var u = state.t / 100;
  var phi = { H2: crossFrac(u, 6), O2: crossFrac(u, 1.5) };
  var LH = 0, LO = 0, RH = 0, RO = 0;

  for (var k = 0; k < mols.length; k++) {
    var m = mols[k], N = m.N, th = (m.idx + 0.5) / N;
    var s = clamp((phi[m.kind] - th) * N / 0.8 + 0.5, 0, 1);
    var x, y, tubeY = CY + m.tubeOff;
    if (s <= 0) { x = m.home[0]; y = m.home[1]; }
    else if (s >= 1) { x = m.away[0]; y = m.away[1]; }
    else if (s < 0.5) { var q = s / 0.5; x = lerp(m.home[0], MID, q); y = lerp(m.home[1], tubeY, q); }
    else { var q2 = (s - 0.5) / 0.5; x = lerp(MID, m.away[0], q2); y = lerp(tubeY, m.away[1], q2); }

