/* ---------- deterministic randomness ---------- */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var rng = mulberry32(20240614);

function samplePts(cx, cy, r, n, minD, rnd) {
  var pts = [], guard = 0;
  while (pts.length < n && guard < 40000) {
    guard++;
    var a = rnd() * Math.PI * 2, rr = r * Math.sqrt(rnd());
    var x = cx + rr * Math.cos(a), y = cy + rr * Math.sin(a), ok = true;
    for (var i = 0; i < pts.length; i++) {
      var dx = x - pts[i][0], dy = y - pts[i][1];
      if (dx * dx + dy * dy < minD * minD) { ok = false; break; }
    }
    if (ok) pts.push([x, y]);
    if (guard % 2500 === 0) minD *= 0.92;
  }
  return pts;
}
function shuffle(arr, rnd) {
  for (var i = arr.length - 1; i > 0; i--) {
    var j = Math.floor(rnd() * (i + 1)), t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }
  return arr;
}
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
