    var onHome = s < 0.5;
    if (m.kind === 'H2') { if (onHome) LH++; else RH++; }
    else { if (onHome) RO++; else LO++; }
  }

  leftCount.h.plain(String(LH)); leftCount.o.plain(String(LO));
  rightCount.h.plain(String(RH)); rightCount.o.plain(String(RO));

  var closed = state.t === 0;
  plugClosed.opacity(closed ? 1 : 0);
  boreOpen.opacity(closed ? 0 : 1);

  if (closed) { capLine1.plain(''); capLine2.plain('Stopcock closed'); capLetter.plain('(a)'); }
  else if (state.t >= 99) { capLine1.plain('Some time after'); capLine2.plain('Stopcock open'); capLetter.plain('(c)'); }
