function update_timeSlider(v) { state.t = clamp(v, 0, 100); render(0); }
function toggle_massMode(on) { state.mass = !!on; render(0); }
function set_stage(s) { setTime(s === 'a' ? 0 : (s === 'b' ? 30 : 100)); }

var playStart = 0;
function trigger_playDiffusion() {
  var btn = document.getElementById('playBtn');
  if (state.playing) { state.playing = false; btn.textContent = '▶ Play diffusion'; render(0); return; }
  state.playing = true; playStart = 0;
  btn.textContent = '■ Stop';
  requestAnimationFrame(playFrame);
}
function playFrame(ts) {
  if (!state.playing) return;
  if (!playStart) playStart = ts;
  var e = (ts - playStart) / 7000;
  state.t = clamp(e * 100, 0, 100);
  var inp = document.getElementById('timeSliderInput');
  var out = document.getElementById('timeSliderVal');
  if (inp) inp.value = state.t;
  if (out) out.value = Math.round(state.t);
  render(ts / 1000);
  if (e >= 1) {
    state.playing = false;
    document.getElementById('playBtn').textContent = '▶ Play diffusion';
    render(0);
    return;
  }
  requestAnimationFrame(playFrame);
}

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'Two gases, one barrier',
    narration: 'The stopcock is closed: every white H₂ molecule is trapped in the left bulb and every red O₂ molecule in the right. Each gas sits on a maximum concentration gradient with nowhere to go.',
    state: { t: 0, mass: false } },
  { title: 'Open the valve',
    narration: 'With the bore clear, molecules begin wandering across. Notice the asymmetry: several white dots have already reached the right bulb while only a few red dots have made it left.',
    state: { t: 25, mass: false } },
  { title: 'Why H₂ leads',
    narration: 'Mass-coded view: H₂ at 2 g/mol carries long fast trails, O₂ at 32 g/mol short slow ones. At the same temperature the lighter gas has the higher average speed, so it spreads about four times faster.',
    state: { t: 40, mass: true } },
  { title: 'Sweep time forward',
    narration: 'Drag the time slider (or press Play) and watch the counters: net transfer slows as each gradient shrinks, even though individual molecules never stop moving.',
    state: { t: 70, mass: true } },
  { title: 'Uniform mixture',
    narration: 'Long after opening, both bulbs contain the same blend of white and red. Molecules still cross the stopcock constantly, but now equally in both directions — equilibrium, not stillness.',
    state: { t: 100, mass: false } }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = clamp(i, 0, STEPS.length - 1);
  var s = STEPS[stepIdx];
  state.playing = false;
  var pb = document.getElementById('playBtn'); if (pb) pb.textContent = '▶ Play diffusion';
  var cb = document.getElementById('massModeInput');
  if (cb) cb.checked = s.state.mass;
  state.mass = s.state.mass;
  setTime(s.state.t);
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

