<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ------------------------------------------------------------------ setup */
var fdraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VT = { w: 1320, h: 400 }, VS = { w: 780, h: 520 };

var GLASS_EDGE = '#a4c4c8', TUBE_FILL = '#e2f0f0';
var METAL = '#d6e8e9', METAL_EDGE = '#9cc0c4';
var RED = '#d8241f', WHITE = '#ffffff', WHITE_EDGE = '#c9d6d6', TXT = '#3a3f42';

var R = 88, D = 110, HB = 21, HM = 14;
var XA = -(D - Math.sqrt(R * R - HB * HB)), XB = -XA;

var glassGrad = fdraw.gradient('radial', function (add) {
  add.stop(0, '#f7fcfc'); add.stop(0.45, '#e6f3f2'); add.stop(1, '#d3e7e7');
});
glassGrad.attr({ cx: 0.34, cy: 0.28, r: 0.8 });

/* ------------------------------------------------------- small utilities */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function lerp(a, b, k) { return a + (b - a) * k; }
function crossFrac(u, a) { return 0.5 * (1 - Math.exp(-a * u * u)) / (1 - Math.exp(-a)); }

function samplePts(cx, cy, r, n, minD, rnd) {
  var pts = [], guard = 0, md = minD;
  while (pts.length < n && guard < 60000) {
    guard++;
    var a = rnd() * Math.PI * 2, rr = r * Math.sqrt(rnd());
    var x = cx + rr * Math.cos(a), y = cy + rr * Math.sin(a), ok = true;
    for (var i = 0; i < pts.length; i++) {
      var dx = x - pts[i][0], dy = y - pts[i][1];
      if (dx * dx + dy * dy < md * md) { ok = false; break; }
    }
    if (ok) pts.push([x, y]);
    if (guard % 3000 === 0) md *= 0.93;
  }
  while (pts.length < n) pts.push([cx, cy]);
  return pts;
}
function shuffle(arr, rnd) {
  for (var i = arr.length - 1; i > 0; i--) {
    var j = Math.floor(rnd() * (i + 1)), t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }
  return arr;
}
function plain(g, s, x, y, size, color, anchor, weight) {
  var t = g.plain(s).font({ family: 'sans-serif', size: size, fill: color || TXT, weight: weight || 'normal' });
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle' });
  return t;
}
function subLabel(parent, x, y, letter, size) {
  var g = parent.group();
  plain(g, letter, x - size * 0.26, y, size, TXT, 'middle');
  plain(g, '2', x + size * 0.32, y + size * 0.20, size * 0.66, TXT, 'middle');
  return g;
}

/* --------------------------------------------------- apparatus generator */
function makeApparatus(parent, seed, interactive) {
  var g = parent.group();
  var rnd = mulberry32(seed);

  /* glassware -------------------------------------------------------- */
  var gGlass = g.group();
  var bulbL = gGlass.circle(R * 2).center(-D, 0).fill(glassGrad).stroke({ color: GLASS_EDGE, width: 3.6 });
  var bulbR = gGlass.circle(R * 2).center(D, 0).fill(glassGrad).stroke({ color: GLASS_EDGE, width: 3.6 });

  var f = function (n) { return Math.round(n * 100) / 100; };
  var topWall = 'M' + f(XA) + ',' + (-HB) +
    ' C' + f(XA + 9) + ',' + (-HB) + ' -11,' + (-HM) + ' -4,' + (-HM) +
    ' L4,' + (-HM) +
    ' C11,' + (-HM) + ' ' + f(XB - 9) + ',' + (-HB) + ' ' + f(XB) + ',' + (-HB);
  var botWall = 'M' + f(XA) + ',' + HB +
    ' C' + f(XA + 9) + ',' + HB + ' -11,' + HM + ' -4,' + HM +
    ' L4,' + HM +
    ' C11,' + HM + ' ' + f(XB - 9) + ',' + HB + ' ' + f(XB) + ',' + HB;
  var tubeFill = topWall + ' L' + f(XB) + ',' + HB +
    ' C' + f(XB - 9) + ',' + HB + ' 11,' + HM + ' 4,' + HM +
    ' L-4,' + HM + ' C-11,' + HM + ' ' + f(XA + 9) + ',' + HB + ' ' + f(XA) + ',' + HB + ' Z';

  gGlass.path(tubeFill).fill(TUBE_FILL).stroke('none');
  gGlass.path(topWall).fill('none').stroke({ color: GLASS_EDGE, width: 3.6, linecap: 'round' });
  gGlass.path(botWall).fill('none').stroke({ color: GLASS_EDGE, width: 3.6, linecap: 'round' });

  /* stopcock ---------------------------------------------------------- */
  var gValve = g.group();
  gValve.rect(13, 11).move(-6.5, 14).fill(METAL).stroke({ color: METAL_EDGE, width: 1.8 });
  gValve.rect(20, 8).move(-10, 24).radius(2).fill(METAL).stroke({ color: METAL_EDGE, width: 1.8 });
  gValve.rect(21, 34).move(-10.5, -17).radius(5).fill(METAL).stroke({ color: METAL_EDGE, width: 2.2 });
  gValve.rect(9, 18).move(-4.5, -32).fill(METAL).stroke({ color: METAL_EDGE, width: 1.8 });
  var handle = gValve.group();
  handle.path('M-7,-30 L-16,-38 L16,-38 L7,-30 Z').fill(METAL).stroke({ color: METAL_EDGE, width: 1.8 });
  handle.ellipse(36, 9).center(0, -38).fill(METAL).stroke({ color: METAL_EDGE, width: 1.8 });
  handle.ellipse(10, 7).center(0, -45).fill(METAL).stroke({ color: METAL_EDGE, width: 1.8 });
  var plug = gValve.ellipse(9, 21).center(0, 0).fill('#f0f8f8').stroke({ color: METAL_EDGE, width: 1.8 });

  if (interactive) {
    gValve.css('cursor', 'pointer');
    gValve.on('mousemove', function (e) { showTooltip('Stopcock — the only path between the bulbs', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Diffusion needs no pump',
          'Opening the stopcock adds no force, no fan and no pressure difference. Molecules simply continue their random, high-speed motion, and that alone erases the concentration difference. ' +
          'At equilibrium molecules still stream through the bore constantly — just equally in both directions.');
      });
    [[bulbL, 'Left'], [bulbR, 'Right']].forEach(function (p) {
      p[0].css('cursor', 'pointer');
      p[0].on('mousemove', function (e) { showTooltip(p[1] + ' bulb — click for the gradient story', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Concentration gradient',
            'Each gas starts entirely in one bulb: maximum concentration on one side, zero on the other. Random motion sends molecules both ways, but more start on the crowded side, ' +
            'so the net flow always runs down the gradient — and it slows as the gradient fades.');
        });
    });
  }

  /* molecules --------------------------------------------------------- */
  var leftSlots = shuffle(samplePts(-D, 0, R - 17, 46, 17.5, rnd), rnd);
  var rightSlots = shuffle(samplePts(D, 0, R - 17, 47, 17.5, rnd), rnd);

  var gTrail = g.group(), gDots = g.group(), mols = [], i;
  for (i = 0; i < 30; i++) {
    mols.push({
      kind: 'H2', idx: i, N: 30, home: leftSlots[i], away: i < 15 ? rightSlots[32 + i] : leftSlots[i],
      rad: 5.4, wob: 3.2, sp1: 1.8 + rnd() * 1.4, sp2: 1.7 + rnd() * 1.4,
      phase: rnd() * 6.28, dir: rnd() * 6.28, tubeOff: rnd() * 12 - 6
    });
  }
  for (i = 0; i < 32; i++) {
    mols.push({
      kind: 'O2', idx: i, N: 32, home: rightSlots[i], away: i < 16 ? leftSlots[30 + i] : rightSlots[i],
      rad: 5.8, wob: 1.4, sp1: 0.5 + rnd() * 0.4, sp2: 0.5 + rnd() * 0.4,
      phase: rnd() * 6.28, dir: rnd() * 6.28, tubeOff: rnd() * 12 - 6
    });
  }

  mols.forEach(function (m) {
    if (interactive) {
      m.trail = gTrail.line(0, 0, 0, 0)
        .stroke({ color: m.kind === 'H2' ? '#ffffff' : RED, width: 3.6, linecap: 'round' }).opacity(0);
    }
    m.el = gDots.circle(m.rad * 2)
      .fill(m.kind === 'H2' ? WHITE : RED)
      .stroke({ color: m.kind === 'H2' ? WHITE_EDGE : '#b21c17', width: m.kind === 'H2' ? 0.9 : 0.6 })
      .center(m.home[0], m.home[1]);
    if (interactive) {
      m.el.css('cursor', 'pointer');
      var tip = m.kind === 'H2'
        ? 'H₂ — hydrogen, M = 2 g/mol · light, fastest average speed'
        : 'O₂ — oxygen, M = 32 g/mol · heavy, ≈4× slower than H₂';
      m.el.on('mousemove', function (e) { showTooltip(tip, e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          if (m.kind === 'H2') {
            showPopup('Hydrogen molecule (H₂)',
              'Molar mass 2 g/mol. At a given temperature every gas has the same average kinetic energy, so the lightest molecules must have the highest speeds (≈1900 m/s at 25 °C). ' +
              'That is why H₂ invades the O₂ bulb first and in larger numbers.');
          } else {
            showPopup('Oxygen molecule (O₂)',
              'Molar mass 32 g/mol — sixteen times heavier than H₂. Equal kinetic energy with sixteen times the mass means about one quarter the average speed (≈480 m/s at 25 °C), ' +
              'so O₂ diffuses roughly four times more slowly: √(32/2) = 4, Graham\'s law.');
          }
        });
    }
  });

  return {
    group: g,
    place: function (x, y, s) { g.attr('transform', 'translate(' + x + ',' + y + ') scale(' + s + ')'); return this; },
    render: function (t, mass, tt) {
      var u = clamp(t, 0, 100) / 100;
      var phi = { H2: crossFrac(u, 6), O2: crossFrac(u, 1.5) };
      var c = { LH: 0, LO: 0, RH: 0, RO: 0 };
      for (var k = 0; k < mols.length; k++) {
        var m = mols[k], th = (m.idx + 0.5) / m.N;
        var s = clamp((phi[m.kind] - th) * m.N / 0.8 + 0.5, 0, 1);
        var x, y, ty = m.tubeOff;
        if (s <= 0) { x = m.home[0]; y = m.home[1]; }
        else if (s >= 1) { x = m.away[0]; y = m.away[1]; }
        else if (s < 0.5) { var q = s / 0.5; x = lerp(m.home[0], 0, q); y = lerp(m.home[1], ty, q); }
        else { var q2 = (s - 0.5) / 0.5; x = lerp(0, m.away[0], q2); y = lerp(ty, m.away[1], q2); }
        if (tt) {
          x += m.wob * Math.sin(tt * m.sp1 + m.phase);
          y += m.wob * Math.cos(tt * m.sp2 + m.phase * 1.7);
        }
        m.el.center(x, y);
        if (m.trail) {
          if (mass) {
            var len = m.kind === 'H2' ? 21 : 7, ang;
            if (s > 0 && s < 1) ang = (m.away[0] > m.home[0]) ? Math.PI : 0; else ang = m.dir;
            m.trail.plot(x + len * Math.cos(ang), y + len * Math.sin(ang), x, y)
              .opacity(m.kind === 'H2' ? 0.85 : 0.45);
          } else m.trail.opacity(0);
        }
        var onHome = s < 0.5;
        if (m.kind === 'H2') { if (onHome) c.LH++; else c.RH++; }
        else { if (onHome) c.RO++; else c.LO++; }
      }
      var closed = (t === 0);
      plug.opacity(closed ? 1 : 0);
      handle.attr('transform', closed ? 'scale(1,1)' : 'scale(0.42,1)');
      return c;
    }
  };
}

/* ============================ TRIPTYCH VIEW (default, matches textbook) == */
var layerT = fdraw.group();
var PANEL_X = [220, 660, 1100], PANEL_Y = 150;
var panelT = [
  { t: 0, cap: ['', 'Stopcock closed'], letter: '(a)' },
  { t: 33, cap: ['', 'Stopcock open'], letter: '(b)' },
  { t: 100, cap: ['Some time after', 'Stopcock open'], letter: '(c)' }
];
var panelInfo = [
  ['Panel (a) — sealed',
    'With the stopcock closed each gas is confined to its own bulb. The concentration gradient is at its maximum, but no molecule can act on it: the barrier, not the molecules, is what keeps the gases separate.'],
  ['Panel (b) — just after opening',
    'Molecules wander across in both directions with no pump or push. Count the dots: several white H₂ molecules have already reached the right bulb while only a couple of red O₂ molecules have crossed the other way.'],
  ['Panel (c) — equilibrium',
    'Long after opening, both bulbs hold the same blend. Molecules keep crossing the stopcock constantly, but now equally in both directions, so nothing changes on average — equilibrium is balance, not stillness.']
];

panelT.forEach(function (p, i) {
  var ap = makeApparatus(layerT, 1301 + i * 977, false);
  ap.place(PANEL_X[i], PANEL_Y, 1);
  ap.render(p.t, false, 0);
  var hit = layerT.rect(400, 260).move(PANEL_X[i] - 200, PANEL_Y - 130).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(panelInfo[i][0] + ' — click to read more', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(panelInfo[i][0], panelInfo[i][1]); });
});

subLabel(layerT, PANEL_X[0] - D, 46, 'H', 25);
subLabel(layerT, PANEL_X[0] + D, 46, 'O', 25);

panelT.forEach(function (p, i) {
  if (p.cap[0]) plain(layerT, p.cap[0], PANEL_X[i], 300, 22, TXT, 'middle');
  plain(layerT, p.cap[1], PANEL_X[i], 328, 22, TXT, 'middle');
  plain(layerT, p.letter, PANEL_X[i], 362, 22, TXT, 'middle');
});

/* ========================= SINGLE INTERACTIVE APPARATUS =================== */
var layerS = fdraw.group();
var SCX = 390, SCY = 200, SS = 1.25;
var single = makeApparatus(layerS, 20240614, true);
single.place(SCX, SCY, SS);

subLabel(layerS, SCX - D * SS, 70, 'H', 21);
subLabel(layerS, SCX + D * SS, 70, 'O', 21);

var leftCount = plain(layerS, '', SCX - D * SS, 350, 16, TXT, 'middle');
var rightCount = plain(layerS, '', SCX + D * SS, 350, 16, TXT, 'middle');

var capA = plain(layerS, '', SCX, 396, 17, TXT, 'middle');
var capB = plain(layerS, 'Stopcock closed', SCX, 420, 17, TXT, 'middle');
var capL = plain(layerS, '(a)', SCX, 448, 17, TXT, 'middle');

var gLegend = layerS.group().opacity(0);
gLegend.rect(268, 66).move(16, 438).radius(6).fill('#f2f9f9').stroke({ color: '#cfe0e1', width: 1 });
gLegend.line(34, 458, 56, 458).stroke({ color: '#ffffff', width: 4, linecap: 'round' });
gLegend.circle(11).center(60, 458).fill(WHITE).stroke({ color: WHITE_EDGE, width: 1 });
plain(gLegend, 'H₂  2 g/mol — fast (long trail)', 72, 462, 13, '#35494c', 'start');
gLegend.line(48, 484, 56, 484).stroke({ color: RED, width: 4, linecap: 'round', opacity: 0.5 });
gLegend.circle(12).center(60, 484).fill(RED);
plain(gLegend, 'O₂  32 g/mol — slow (short trail)', 72, 488, 13, '#35494c', 'start');

/* ------------------------------------------------------------ view state */
var state = { single: false, t: 0, mass: false, playing: false };

function applyView() {
  if (state.single) {
    fdraw.viewbox(0, 0, VS.w, VS.h);
    layerT.hide(); layerS.show();
  } else {
    fdraw.viewbox(0, 0, VT.w, VT.h);
    layerS.hide(); layerT.show();
  }
}

function renderSingle(tt) {
  var c = single.render(state.t, state.mass, tt || 0);
  leftCount.plain('H₂: ' + c.LH + '    O₂: ' + c.LO);
  rightCount.plain('H₂: ' + c.RH + '    O₂: ' + c.RO);
  var closed = state.t === 0;
  if (closed) { capA.plain(''); capB.plain('Stopcock closed'); capL.plain('(a)'); }
  else if (state.t >= 99) { capA.plain('Some time after'); capB.plain('Stopcock open'); capL.plain('(c)'); }
  else { capA.plain(''); capB.plain('Stopcock open'); capL.plain('(b)'); }
  gLegend.opacity(state.mass ? 1 : 0);
  var st = closed ? 'a' : (state.t >= 99 ? 'c' : 'b');
  ['a', 'b', 'c'].forEach(function (s2) {
    var b = document.getElementById('stage' + s2.toUpperCase() + 'Btn');
    if (b) b.className = (state.single && s2 === st) ? 'active' : '';
  });
  var vb = document.getElementById('viewModeInput');
  if (vb) vb.checked = state.single;
}

function syncSlider() {
  var inp = document.getElementById('timeSliderInput');
  var out = document.getElementById('timeSliderVal');
  if (inp) inp.value = state.t;
  if (out) out.value = Math.round(state.t);
}
function setTime(v) { state.t = clamp(v, 0, 100); syncSlider(); renderSingle(0); }
function ensureSingle() { if (!state.single) { state.single = true; applyView(); } }

/* -------------------------------------------------------- UI handlers ---- */
function toggle_viewMode(on) { state.single = !!on; applyView(); renderSingle(0); }
function update_timeSlider(v) { ensureSingle(); state.t = clamp(v, 0, 100); renderSingle(0); }
function toggle_massMode(on) { state.mass = !!on; if (state.mass) ensureSingle(); renderSingle(0); }
function set_stage(s) { ensureSingle(); setTime(s === 'a' ? 0 : (s === 'b' ? 33 : 100)); }

var playStart = 0;
function trigger_playDiffusion() {
  var btn = document.getElementById('playBtn');
  ensureSingle();
  if (state.playing) { state.playing = false; btn.textContent = '▶ Play diffusion'; renderSingle(0); return; }
  state.playing = true; playStart = 0; btn.textContent = '■ Stop';
  requestAnimationFrame(playFrame);
}
function playFrame(ts) {
  if (!state.playing) return;
  if (!playStart) playStart = ts;
  var e = (ts - playStart) / 8000;
  state.t = clamp(e * 100, 0, 100);
  syncSlider();
  renderSingle(ts / 1000);
  if (e >= 1) {
    state.playing = false;
    document.getElementById('playBtn').textContent = '▶ Play diffusion';
    renderSingle(0);
    return;
  }
  requestAnimationFrame(playFrame);
}

/* ------------------------------------------------------------ demo steps */
