              'That is why H₂ invades the O₂ bulb first and in larger numbers.');
          } else {
            showPopup('Oxygen molecule (O₂)',
              'Molar mass 32 g/mol — sixteen times heavier than H₂. Equal kinetic energy with sixteen times the mass means about one quarter the average speed (≈480 m/s at 25 °C), ' +
              'so O₂ diffuses roughly four times more slowly: √(32/2) = 4, Graham\'s law.');
          }
        });
    }
  });

  return {
    group: g,
    place: function (x, y, s) { g.attr('transform', 'translate(' + x + ',' + y + ') scale(' + s + ')'); return this; },
    render: function (t, mass, tt) {
      var u = clamp(t, 0, 100) / 100;
      var phi = { H2: crossFrac(u, 6), O2: crossFrac(u, 1.5) };
      var c = { LH: 0, LO: 0, RH: 0, RO: 0 };
      for (var k = 0; k < mols.length; k++) {
        var m = mols[k], th = (m.idx + 0.5) / m.N;
        var s = clamp((phi[m.kind] - th) * m.N / 0.8 + 0.5, 0, 1);
        var x, y, ty = m.tubeOff;
        if (s <= 0) { x = m.home[0]; y = m.home[1]; }
        else if (s >= 1) { x = m.away[0]; y = m.away[1]; }
        else if (s < 0.5) { var q = s / 0.5; x = lerp(m.home[0], 0, q); y = lerp(m.home[1], ty, q); }
        else { var q2 = (s - 0.5) / 0.5; x = lerp(0, m.away[0], q2); y = lerp(ty, m.away[1], q2); }
        if (tt) {
          x += m.wob * Math.sin(tt * m.sp1 + m.phase);
          y += m.wob * Math.cos(tt * m.sp2 + m.phase * 1.7);
        }
        m.el.center(x, y);
        if (m.trail) {
          if (mass) {
            var len = m.kind === 'H2' ? 21 : 7, ang;
            if (s > 0 && s < 1) ang = (m.away[0] > m.home[0]) ? Math.PI : 0; else ang = m.dir;
            m.trail.plot(x + len * Math.cos(ang), y + len * Math.sin(ang), x, y)
              .opacity(m.kind === 'H2' ? 0.85 : 0.45);
          } else m.trail.opacity(0);
        }
        var onHome = s < 0.5;
        if (m.kind === 'H2') { if (onHome) c.LH++; else c.RH++; }
        else { if (onHome) c.RO++; else c.LO++; }
      }
      var closed = (t === 0);
      plug.opacity(closed ? 1 : 0);
      handle.attr('transform', closed ? 'scale(1,1)' : 'scale(0.42,1)');
      return c;
    }
  };
}

/* ============================ TRIPTYCH VIEW (default, matches textbook) == */
var layerT = fdraw.group();
var PANEL_X = [220, 660, 1100], PANEL_Y = 150;
var panelT = [
  { t: 0, cap: ['', 'Stopcock closed'], letter: '(a)' },
  { t: 33, cap: ['', 'Stopcock open'], letter: '(b)' },
  { t: 100, cap: ['Some time after', 'Stopcock open'], letter: '(c)' }
];
var panelInfo = [
  ['Panel (a) — sealed',
    'With the stopcock closed each gas is confined to its own bulb. The concentration gradient is at its maximum, but no molecule can act on it: the barrier, not the molecules, is what keeps the gases separate.'],
  ['Panel (b) — just after opening',
    'Molecules wander across in both directions with no pump or push. Count the dots: several white H₂ molecules have already reached the right bulb while only a couple of red O₂ molecules have crossed the other way.'],
  ['Panel (c) — equilibrium',
    'Long after opening, both bulbs hold the same blend. Molecules keep crossing the stopcock constantly, but now equally in both directions, so nothing changes on average — equilibrium is balance, not stillness.']
];

panelT.forEach(function (p, i) {
  var ap = makeApparatus(layerT, 1301 + i * 977, false);
  ap.place(PANEL_X[i], PANEL_Y, 1);
  ap.render(p.t, false, 0);
  var hit = layerT.rect(400, 260).move(PANEL_X[i] - 200, PANEL_Y - 130).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(panelInfo[i][0] + ' — click to read more', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(panelInfo[i][0], panelInfo[i][1]); });
});

subLabel(layerT, PANEL_X[0] - D, 46, 'H', 25);
subLabel(layerT, PANEL_X[0] + D, 46, 'O', 25);

panelT.forEach(function (p, i) {
  if (p.cap[0]) plain(layerT, p.cap[0], PANEL_X[i], 300, 22, TXT, 'middle');
  plain(layerT, p.cap[1], PANEL_X[i], 328, 22, TXT, 'middle');
  plain(layerT, p.letter, PANEL_X[i], 362, 22, TXT, 'middle');
});

/* ========================= SINGLE INTERACTIVE APPARATUS =================== */
var layerS = fdraw.group();
var SCX = 390, SCY = 200, SS = 1.25;
var single = makeApparatus(layerS, 20240614, true);
single.place(SCX, SCY, SS);

subLabel(layerS, SCX - D * SS, 70, 'H', 21);
subLabel(layerS, SCX + D * SS, 70, 'O', 21);

var leftCount = plain(layerS, '', SCX - D * SS, 350, 16, TXT, 'middle');
var rightCount = plain(layerS, '', SCX + D * SS, 350, 16, TXT, 'middle');

var capA = plain(layerS, '', SCX, 396, 17, TXT, 'middle');
var capB = plain(layerS, 'Stopcock closed', SCX, 420, 17, TXT, 'middle');
var capL = plain(layerS, '(a)', SCX, 448, 17, TXT, 'middle');

var gLegend = layerS.group().opacity(0);
gLegend.rect(268, 66).move(16, 438).radius(6).fill('#f2f9f9').stroke({ color: '#cfe0e1', width: 1 });
gLegend.line(34, 458, 56, 458).stroke({ color: '#ffffff', width: 4, linecap: 'round' });
gLegend.circle(11).center(60, 458).fill(WHITE).stroke({ color: WHITE_EDGE, width: 1 });
plain(gLegend, 'H₂  2 g/mol — fast (long trail)', 72, 462, 13, '#35494c', 'start');
gLegend.line(48, 484, 56, 484).stroke({ color: RED, width: 4, linecap: 'round', opacity: 0.5 });
gLegend.circle(12).center(60, 484).fill(RED);
plain(gLegend, 'O₂  32 g/mol — slow (short trail)', 72, 488, 13, '#35494c', 'start');

/* ------------------------------------------------------------ view state */
var state = { single: false, t: 0, mass: false, playing: false };

function applyView() {
  if (state.single) {
    fdraw.viewbox(0, 0, VS.w, VS.h);
    layerT.hide(); layerS.show();
  } else {
    fdraw.viewbox(0, 0, VT.w, VT.h);
    layerS.hide(); layerT.show();
  }
}

function renderSingle(tt) {
  var c = single.render(state.t, state.mass, tt || 0);
  leftCount.plain('H₂: ' + c.LH + '    O₂: ' + c.LO);
  rightCount.plain('H₂: ' + c.RH + '    O₂: ' + c.RO);
  var closed = state.t === 0;
  if (closed) { capA.plain(''); capB.plain('Stopcock closed'); capL.plain('(a)'); }
  else if (state.t >= 99) { capA.plain('Some time after'); capB.plain('Stopcock open'); capL.plain('(c)'); }
  else { capA.plain(''); capB.plain('Stopcock open'); capL.plain('(b)'); }
  gLegend.opacity(state.mass ? 1 : 0);
  var st = closed ? 'a' : (state.t >= 99 ? 'c' : 'b');
  ['a', 'b', 'c'].forEach(function (s2) {
    var b = document.getElementById('stage' + s2.toUpperCase() + 'Btn');
    if (b) b.className = (state.single && s2 === st) ? 'active' : '';
  });
  var vb = document.getElementById('viewModeInput');
  if (vb) vb.checked = state.single;
}

function syncSlider() {
  var inp = document.getElementById('timeSliderInput');
  var out = document.getElementById('timeSliderVal');
  if (inp) inp.value = state.t;
  if (out) out.value = Math.round(state.t);
}
function setTime(v) { state.t = clamp(v, 0, 100); syncSlider(); renderSingle(0); }
function ensureSingle() { if (!state.single) { state.single = true; applyView(); } }

/* -------------------------------------------------------- UI handlers ---- */
function toggle_viewMode(on) { state.single = !!on; applyView(); renderSingle(0); }
function update_timeSlider(v) { ensureSingle(); state.t = clamp(v, 0, 100); renderSingle(0); }
function toggle_massMode(on) { state.mass = !!on; if (state.mass) ensureSingle(); renderSingle(0); }
function set_stage(s) { ensureSingle(); setTime(s === 'a' ? 0 : (s === 'b' ? 33 : 100)); }

var playStart = 0;
function trigger_playDiffusion() {
  var btn = document.getElementById('playBtn');
  ensureSingle();
  if (state.playing) { state.playing = false; btn.textContent = '▶ Play diffusion'; renderSingle(0); return; }
  state.playing = true; playStart = 0; btn.textContent = '■ Stop';
  requestAnimationFrame(playFrame);
}
function playFrame(ts) {
  if (!state.playing) return;
  if (!playStart) playStart = ts;
  var e = (ts - playStart) / 8000;
  state.t = clamp(e * 100, 0, 100);
  syncSlider();
  renderSingle(ts / 1000);
  if (e >= 1) {
    state.playing = false;
    document.getElementById('playBtn').textContent = '▶ Play diffusion';
    renderSingle(0);
    return;
  }
  requestAnimationFrame(playFrame);
}

/* ------------------------------------------------------------ demo steps */
var STEPS = [
  {
    title: 'The textbook figure',
    narration: 'Three snapshots of the same apparatus: (a) the stopcock is closed with H₂ sealed left and O₂ sealed right, (b) the valve has just been opened and molecules begin crossing, (c) long afterward both bulbs hold the same mixture.',
    state: { single: false, t: 0, mass: false }
  },
  {
    title: 'Zoom into one apparatus',
    narration: 'Switch to the single enlarged apparatus, still sealed. Counters under each bulb read H₂: 30, O₂: 0 on the left and H₂: 0, O₂: 32 on the right — a maximum gradient with nowhere to go.',
    state: { single: true, t: 0, mass: false }
  },
  {
    title: 'Open the valve',
    narration: 'Turn the stopcock and the bore clears. Molecules wander across in both directions, yet the counters already show an asymmetry: more white H₂ dots have reached the right bulb than red O₂ dots have reached the left.',
    state: { single: true, t: 25, mass: false }
  },
  {
    title: 'Why H₂ leads',
    narration: 'In the mass-coded view H₂ (2 g/mol) carries long fast trails and O₂ (32 g/mol) short slow ones. Same temperature means the same average kinetic energy, so the lighter gas moves about four times faster and spreads sooner.',
    state: { single: true, t: 45, mass: true }
  },
  {
    title: 'Uniform mixture',
    narration: 'Push time to the end: both bulbs show the same salt-and-pepper blend and the counters match. Molecules still cross the stopcock constantly, now equally in both directions — equilibrium is balance, not stillness.',
    state: { single: true, t: 100, mass: false }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = clamp(i, 0, STEPS.length - 1);
  var s = STEPS[stepIdx];
  state.playing = false;
  var pb = document.getElementById('playBtn'); if (pb) pb.textContent = '▶ Play diffusion';
  var cb = document.getElementById('massModeInput'); if (cb) cb.checked = s.state.mass;
  state.mass = s.state.mass;
  state.single = s.state.single;
  state.t = s.state.t;
  applyView();
  syncSlider();
  renderSingle(0);
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

