// @FIGURE_CODE_BEGIN
/* ------------------------------------------------------------------ setup */
var fdraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VT = { w: 1240, h: 350 }, VS = { w: 740, h: 560 };

var GLASS_EDGE = '#a4c4c8', TUBE_FILL = '#e2f0f0';
var METAL = '#d6e8e9', METAL_EDGE = '#9cc0c4';
var RED = '#d8241f', WHITE = '#ffffff', WHITE_EDGE = '#c9d6d6', TXT = '#3a3f42';

/* apparatus geometry (local units, faithful to the source proportions) */
var R = 73, D = 103, HB = 21, HM = 14, RIN = R - 13;
var XA = -(D - Math.sqrt(R * R - HB * HB)), XB = -XA;
var RAD_H = 6.0, RAD_O = 6.3;

var glassGrad = fdraw.gradient('radial', function (add) {
  add.stop(0, '#f8fcfc'); add.stop(0.45, '#e6f3f2'); add.stop(1, '#d3e7e7');
});
glassGrad.attr({ cx: 0.34, cy: 0.28, r: 0.8 });

/* ------------------------------------------------------- small utilities */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function lerp(a, b, k) { return a + (b - a) * k; }
function crossFrac(u, a) { return 0.5 * (1 - Math.exp(-a * u * u)) / (1 - Math.exp(-a)); }

/* Mitchell best-candidate sampling: blue-noise points that fill the disc
   uniformly (no central hole, no edge ring) — boundary distance is folded in
   so candidates are not pushed against the rim.                           */
function discSlots(cx, cy, r, n, rnd) {
  var pts = [], i, c, j;
  for (i = 0; i < n; i++) {
    var best = null, bestD = -1, K = 16;
    for (c = 0; c < K; c++) {
      var a = rnd() * Math.PI * 2, rr = r * Math.sqrt(rnd());
      var x = cx + rr * Math.cos(a), y = cy + rr * Math.sin(a);
      var d = Infinity;
      for (j = 0; j < pts.length; j++) {
        var dx = x - pts[j][0], dy = y - pts[j][1], dd = dx * dx + dy * dy;
        if (dd < d) d = dd;
      }
      var db = (r - rr) * 1.7;
      if (db * db < d) d = db * db;
      if (d > bestD) { bestD = d; best = [x, y]; }
    }
    pts.push(best);
  }
  return pts;
}
function shuffle(arr, rnd) {
  for (var i = arr.length - 1; i > 0; i--) {
    var j = Math.floor(rnd() * (i + 1)), t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }
  return arr;
}
function plain(g, s, x, y, size, color, anchor, weight) {
  var t = g.plain(s).font({ family: 'sans-serif', size: size, fill: color || TXT, weight: weight || 'normal' });
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle' });
  return t;
}
function subLabel(parent, x, y, letter, size) {
  var g = parent.group();
  plain(g, letter, x - size * 0.27, y, size, TXT, 'middle');
  plain(g, '2', x + size * 0.33, y + size * 0.20, size * 0.66, TXT, 'middle');
  return g;
}

/* --------------------------------------------------- apparatus generator */
function makeApparatus(parent, seed, interactive) {
  var g = parent.group();
  var rnd = mulberry32(seed);

  /* glassware -------------------------------------------------------- */
  var gGlass = g.group();
  var bulbL = gGlass.circle(R * 2).center(-D, 0).fill(glassGrad).stroke({ color: GLASS_EDGE, width: 3.2 });
  var bulbR = gGlass.circle(R * 2).center(D, 0).fill(glassGrad).stroke({ color: GLASS_EDGE, width: 3.2 });

  var f = function (n) { return Math.round(n * 100) / 100; };
  var topWall = 'M' + f(XA) + ',' + (-HB) +
    ' C' + f(XA + 8) + ',' + (-HB) + ' -10,' + (-HM) + ' -4,' + (-HM) +
    ' L4,' + (-HM) +
    ' C10,' + (-HM) + ' ' + f(XB - 8) + ',' + (-HB) + ' ' + f(XB) + ',' + (-HB);
  var botWall = 'M' + f(XA) + ',' + HB +
    ' C' + f(XA + 8) + ',' + HB + ' -10,' + HM + ' -4,' + HM +
    ' L4,' + HM +
    ' C10,' + HM + ' ' + f(XB - 8) + ',' + HB + ' ' + f(XB) + ',' + HB;
  var tubeFill = topWall + ' L' + f(XB) + ',' + HB +
    ' C' + f(XB - 8) + ',' + HB + ' 10,' + HM + ' 4,' + HM +
    ' L-4,' + HM + ' C-10,' + HM + ' ' + f(XA + 8) + ',' + HB + ' ' + f(XA) + ',' + HB + ' Z';

  gGlass.path(tubeFill).fill(TUBE_FILL).stroke('none');
  gGlass.path(topWall).fill('none').stroke({ color: GLASS_EDGE, width: 3.2, linecap: 'round' });
  gGlass.path(botWall).fill('none').stroke({ color: GLASS_EDGE, width: 3.2, linecap: 'round' });

  /* stopcock ---------------------------------------------------------- */
  var gValve = g.group();
  gValve.rect(11, 9.5).move(-5.5, 12).fill(METAL).stroke({ color: METAL_EDGE, width: 1.6 });
  gValve.rect(17, 7).move(-8.5, 20.5).radius(2).fill(METAL).stroke({ color: METAL_EDGE, width: 1.6 });
  gValve.rect(18, 29).move(-9, -14.5).radius(4).fill(METAL).stroke({ color: METAL_EDGE, width: 2 });
  gValve.rect(8, 15).move(-4, -27).fill(METAL).stroke({ color: METAL_EDGE, width: 1.6 });
  var handle = gValve.group();
  handle.path('M-6,-25.5 L-13.5,-32 L13.5,-32 L6,-25.5 Z').fill(METAL).stroke({ color: METAL_EDGE, width: 1.6 });
  handle.ellipse(31, 8).center(0, -32).fill(METAL).stroke({ color: METAL_EDGE, width: 1.6 });
  handle.ellipse(8.5, 6).center(0, -38).fill(METAL).stroke({ color: METAL_EDGE, width: 1.6 });
  var plug = gValve.ellipse(8, 18).center(0, 0).fill('#f0f8f8').stroke({ color: METAL_EDGE, width: 1.6 });

  if (interactive) {
    gValve.css('cursor', 'pointer');
    gValve.on('mousemove', function (e) { showTooltip('Stopcock — the only path between the bulbs', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Diffusion needs no pump',
          'Opening the stopcock adds no force, no fan and no pressure difference. Molecules simply continue their random, high-speed motion, and that alone erases the concentration difference. ' +
          'At equilibrium molecules still stream through the bore constantly — just equally in both directions.');
      });
    [[bulbL, 'Left'], [bulbR, 'Right']].forEach(function (p) {
      p[0].css('cursor', 'pointer');
      p[0].on('mousemove', function (e) { showTooltip(p[1] + ' bulb — click for the gradient story', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Concentration gradient',
            'Each gas starts entirely in one bulb: maximum concentration on one side, zero on the other. Random motion sends molecules both ways, but more start on the crowded side, ' +
            'so the net flow always runs down the gradient — and it slows as the gradient fades.');
        });
    });
  }

  /* molecules --------------------------------------------------------- */
  var leftSlots = shuffle(discSlots(-D, 0, RIN, 48, rnd), rnd);
  var rightSlots = shuffle(discSlots(D, 0, RIN, 48, rnd), rnd);

  var gTrail = g.group(), gDots = g.group(), mols = [], i;
  for (i = 0; i < 30; i++) {
    mols.push({
      kind: 'H2', idx: i, N: 30, home: leftSlots[i], away: i < 15 ? rightSlots[32 + i] : leftSlots[i],
      rad: RAD_H, wob: 2.6, sp1: 1.8 + rnd() * 1.4, sp2: 1.7 + rnd() * 1.4,
      phase: rnd() * 6.28, dir: rnd() * 6.28, tubeOff: rnd() * 11 - 5.5
    });
  }
  for (i = 0; i < 32; i++) {
    mols.push({
      kind: 'O2', idx: i, N: 32, home: rightSlots[i], away: i < 16 ? leftSlots[30 + i] : rightSlots[i],
      rad: RAD_O, wob: 1.1, sp1: 0.5 + rnd() * 0.4, sp2: 0.5 + rnd() * 0.4,
      phase: rnd() * 6.28, dir: rnd() * 6.28, tubeOff: rnd() * 11 - 5.5
    });
  }

  mols.forEach(function (m) {
    if (interactive) {
      m.trail = gTrail.line(0, 0, 0, 0)
        .stroke({ color: m.kind === 'H2' ? '#ffffff' : RED, width: 3.2, linecap: 'round' }).opacity(0);
    }
    m.el = gDots.circle(m.rad * 2)
      .fill(m.kind === 'H2' ? WHITE : RED)
      .stroke({ color: m.kind === 'H2' ? WHITE_EDGE : '#b21c17', width: m.kind === 'H2' ? 0.9 : 0.5 })
      .center(m.home[0], m.home[1]);
    if (interactive) {
      m.el.css('cursor', 'pointer');
      var tip = m.kind === 'H2'
        ? 'H₂ — hydrogen, M = 2 g/mol · light, fastest average speed'
        : 'O₂ — oxygen, M = 32 g/mol · heavy, ≈4× slower than H₂';
      m.el.on('mousemove', function (e) { showTooltip(tip, e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          if (m.kind === 'H2') {
            showPopup('Hydrogen molecule (H₂)',
              'Molar mass 2 g/mol. At a given temperature every gas has the same average kinetic energy, so the lightest molecules must have the highest speeds (≈1900 m/s at 25 °C). ' +
              'That is why H₂ invades the O₂ bulb first and in larger numbers.');
          } else {
            showPopup('Oxygen molecule (O₂)',
              'Molar mass 32 g/mol — sixteen times heavier than H₂. Equal kinetic energy with sixteen times the mass means about one quarter the average speed (≈480 m/s at 25 °C), ' +
              'so O₂ diffuses roughly four times more slowly: √(32/2) = 4, Graham\'s law.');
          }
        });
    }
  });

  return {
    group: g,
    place: function (x, y, s) { g.attr('transform', 'translate(' + x + ',' + y + ') scale(' + s + ')'); return this; },
    render: function (t, mass, tt) {
      var u = clamp(t, 0, 100) / 100;
      var phi = { H2: crossFrac(u, 6), O2: crossFrac(u, 1.5) };
      var c = { LH: 0, LO: 0, RH: 0, RO: 0 };
      for (var k = 0; k < mols.length; k++) {
        var m = mols[k], th = (m.idx + 0.5) / m.N;
        var s = clamp((phi[m.kind] - th) * m.N / 0.8 + 0.5, 0, 1);
        var x, y, ty = m.tubeOff;
        if (s <= 0) { x = m.home[0]; y = m.home[1]; }
        else if (s >= 1) { x = m.away[0]; y = m.away[1]; }
        else if (s < 0.5) { var q = s / 0.5; x = lerp(m.home[0], 0, q); y = lerp(m.home[1], ty, q); }
        else { var q2 = (s - 0.5) / 0.5; x = lerp(0, m.away[0], q2); y = lerp(ty, m.away[1], q2); }
        if (tt) {
          x += m.wob * Math.sin(tt * m.sp1 + m.phase);
          y += m.wob * Math.cos(tt * m.sp2 + m.phase * 1.7);
        }
        m.el.center(x, y);
        if (m.trail) {
          if (mass) {
            var len = m.kind === 'H2' ? 17 : 6, ang;
            if (s > 0 && s < 1) ang = (m.away[0] > m.home[0]) ? Math.PI : 0; else ang = m.dir;
            m.trail.plot(x + len * Math.cos(ang), y + len * Math.sin(ang), x, y)
              .opacity(m.kind === 'H2' ? 0.85 : 0.45);
          } else m.trail.opacity(0);
        }
        var onHome = s < 0.5;
        if (m.kind === 'H2') { if (onHome) c.LH++; else c.RH++; }
        else { if (onHome) c.RO++; else c.LO++; }
      }
      var closed = (t === 0);
      plug.opacity(closed ? 1 : 0);
      handle.attr('transform', closed ? 'scale(1,1)' : 'scale(0.42,1)');
      return c;
    }
  };
}

